// Üretilen dosya: tool/ozgun/uret.py. Bilim · Okyanus ve su bilimi: akıntılar, gelgit, deniz canlıları ortamı, su döngüsü (kolay).
const ozScience9Kolay = <(String, String, List<String>, String)>[
  ('Dünya\'daki toplam suyun yaklaşık yüzde kaçı okyanus ve denizlerde tuzlu su olarak bulunur?', 'Yaklaşık %97', ['Yaklaşık %71', 'Yaklaşık %85', 'Yaklaşık %60,5'], 'Yerkürenin suyunun yaklaşık %97\'si okyanus ve denizlerdedir; %71 ise okyanusların yüzeyde kapladığı alan oranıdır, karıştırılmamalıdır.'),
  ('Yeryüzü yüzeyinin yaklaşık ne kadarı okyanus ve denizlerle kaplıdır?', 'Yaklaşık %71', ['Yaklaşık %51', 'Yaklaşık %91', 'Yaklaşık %39,5'], 'Okyanus ve denizler Dünya yüzeyinin yaklaşık %71\'ini kaplar; karalar kabaca %29\'luk paya sahiptir.'),
  ('Yüzölçümü bakımından tüm kıtaların toplam alanından daha büyük olan okyanus hangisidir?', 'Büyük Okyanus', ['Atlas Okyanusu', 'Hint Okyanusu', 'Arktik (Kuzey Buz) Okyanusu'], 'Pasifik, Dünya yüzeyinin yaklaşık üçte birini kaplar ve bütün karaların toplam alanından büyüktür.'),
  ('Atmosfere giren su buharının büyük bölümünün kaynağı hangisidir?', 'Okyanus yüzeyinden buharlaşma', ['Bitkilerin terlemesi', 'Göllerden buharlaşma', 'Kar ve buz örtüsünden süblimleşme'], 'Küresel buharlaşmanın yaklaşık %85\'inden fazlası okyanuslardan gerçekleşir; karalardan gelen pay daha küçüktür.'),
  ('Bitki terlemesinde su buharı en çok bitkinin hangi yapısından atmosfere geçer?', 'Yapraklardaki stomalardan', ['Kök tüylerinden', 'Gövdedeki odun borularından', 'Çiçeklerin taç yapraklarından'], 'Su kökten alınıp odun borularıyla taşınır, ancak buhar olarak çoğunlukla yaprak yüzeyindeki stomalardan çıkar.'),
  ('Yüksek dağlarda kuru ve rüzgârlı havada kar örtüsü erimeden incelir. Kar suyunun bu biçimde atmosfere geçmesine ne ad verilir?', 'Süblimleşme', ['Yoğuşma', 'Kırağılaşma', 'Yüzey akışına geçme'], 'Katı hâldeki kar, sıvı evreye geçmeden doğrudan su buharına dönüşür; bu süreç kuru, güneşli ve rüzgârlı yüksek dağlarda belirgindir.'),
  ('Yağış suyunun toprak yüzeyinden toprağın içine girmesi sürecine ne ad verilir?', 'İnfiltrasyon', ['Transpirasyon', 'Adveksiyon', 'Ablasyon'], 'İnfiltrasyon (sızma), suyun yüzeyden toprağa girişidir; toprağın gözenekliliği ve doygunluğu hızını belirler.'),
  ('Su döngüsünde suyu buharlaştırarak yukarı taşıyan enerjinin kaynağı ile suyu yeniden yeryüzüne ve denize indiren etken sırasıyla hangileridir?', 'Güneş enerjisi ve yerçekimi', ['Yer içi ısısı ve rüzgâr', 'Rüzgâr ve Güneş enerjisi', 'Yerçekimi ve yer içindeki magma ısısı'], 'Güneş ışınımı buharlaşmayı sağlar; yoğuşan su yağış olarak düşer ve akarsularla denize yerçekimi sayesinde iner.'),
  ('Aşağıdakilerden hangisi yeryüzüne düşen yağış suyunun izleyebileceği yollardan biri değildir?', 'Yer çekirdeğine doğru inerek tükenmesi', ['Yüzey akışıyla akarsuya karışması', 'Toprağa sızıp yeraltındaki suyu beslemesi', 'Buharlaşarak atmosfere dönmesi'], 'Yağış suyu yüzey akışı, sızma ve buharlaşma yollarıyla dağılır; yerin derinliklerinde tükenme döngünün bir parçası değildir.'),
  ('Okyanusta tuzluluğun derinlikle hızla değiştiği geçiş katmanına ne ad verilir?', 'Haloklin', ['Termoklin', 'Piknoklin', 'Nefeloid katman'], 'Halo- tuz, -klin eğim anlamına gelir; haloklin tuzluluğun dikey yönde hızla değiştiği katmandır.'),
  ('Büyük bir akarsuyun denize döküldüğü bir bölgede yüzeydeki tuzluluk ölçülüyor. Ağızdan açık denize doğru gidildikçe ne beklenir?', 'Tuzluluk giderek artar', ['Tuzluluk giderek azalır', 'Tuzluluk hiç değişmez', 'Tuzluluk önce sıfıra iner sonra artar'], 'Akarsuyun tatlı suyu ağız çevresinde deniz suyunu seyreltir; karışım uzaklaştıkça açık deniz değerine yaklaşır.'),
  ('Okyanusta sıcaklığın derinlikle hızla düştüğü geçiş katmanına ne ad verilir?', 'Termoklin', ['Haloklin', 'Kemoklin', 'Lizoklin katmanı'], 'Termoklin, ılık yüzey katmanını soğuk derin sulardan ayıran ve sıcaklığın kısa mesafede çok değiştiği katmandır.'),
  ('Açık okyanusta yüzeyden yaklaşık 200 metreye kadar uzanan, fotosentez için yeterli ışığın bulunduğu katmana ne ad verilir?', 'Epipelajik bölge', ['Batipelajik bölge', 'Abisopelajik bölge', 'Hadal bölge'], 'Epipelajik (ışıklı) bölge, fitoplanktonun fotosentez yapabildiği en üst katmandır ve deniz yaşamının çoğunu barındırır.'),
  ('Yaklaşık 200 ile 1000 metre arasında kalan, ışığın fotosentez için yetersiz ama tamamen yok olmadığı katmana halk arasında ne denir?', 'Alacakaranlık bölgesi', ['Gece yarısı bölgesi', 'Gelgit arası bölge', 'Çukur (hadal) bölgesi'], 'Mezopelajik bölgeye zayıf mavi ışık ulaşır; bu yüzden \'alacakaranlık bölgesi\' olarak anılır.'),
  ('Yüksek suyla alçak su düzeyleri arasında kalan, günde bir ya da iki kez su altında kalıp açığa çıkan kıyı şeridine ne ad verilir?', 'Gelgit arası bölge', ['Afotik bölge', 'Kıta yamacı', 'Abisal düzlük'], 'Bu bölgedeki canlılar kurumaya, dalga darbesine ve tuzluluk ile sıcaklık değişimlerine dayanıklı olmak zorundadır.'),
  ('Bir derin deniz balığı yaklaşık 3000 metre derinlikte yaşıyor. Bu balığın yaşadığı ortam için hangisi kesinlikle doğrudur?', 'Güneş ışığı ulaşmaz, sürekli karanlıktır', ['Fotosentez yapan algler boldur', 'Sıcaklık yüzeye göre daha yüksektir', 'Basınç yüzeydekine yakındır'], 'Bu derinlik batipelajik bölgededir; Güneş ışığı yaklaşık 1000 metrenin altına ulaşamaz, su soğuk ve basınç çok yüksektir.'),
  ('Berrak deniz suyunda gün ışığının renkleri derine inerken hangisi en çabuk soğurulur?', 'Kırmızı', ['Mavi', 'Yeşil', 'Sarı'], 'Su molekülleri uzun dalga boylu kırmızı ışığı ilk birkaç metrede soğurur; mavi ışık en derine kadar iner.'),
  ('Deniz suyunda derinlik arttıkça yaklaşık her 10 metrede basınç ne kadar artar?', 'Yaklaşık 1 atmosfer', ['Yaklaşık 0,1 atmosfer', 'Yaklaşık 10 atmosfer', 'Yaklaşık 100 atmosfer'], '10 metrelik deniz suyu sütununun ağırlığı yaklaşık bir atmosfer basıncına eşittir.'),
  ('Yüzeyde ağzı sıkıca kapatılmış boş bir plastik şişe derin bir dalışta aşağı indirildiğinde ne gözlenir?', 'Şişe giderek içe doğru çöker', ['Şişe giderek şişip patlar', 'Şişenin biçimi hiç değişmez', 'Şişe ağırlaşıp yüzeye fırlar'], 'İçerideki hava yüzey basıncındadır; derindeki büyük dış basınç şişeyi içe doğru sıkıştırır.'),
  ('Deniz suyunda sesin yayılma hızı yaklaşık ne kadardır?', 'Yaklaşık 1500 m/s', ['Yaklaşık 340 m/s', 'Yaklaşık 150 m/s', 'Yaklaşık 15 000 m/s'], 'Ses deniz suyunda havadakinin yaklaşık dört buçuk katı hızla, saniyede yaklaşık 1,5 km yol alır.'),
  ('Okyanus tabanının haritasını çıkarmak için gemilerden ses dalgası gönderip yankıyı ölçen sistemlere genel olarak ne ad verilir?', 'Sonar', ['Radar', 'Lidar', 'Sismometre'], 'Sonar ses dalgalarını kullanır; radyo dalgaları (radar) ve ışık (lidar) deniz suyunda çok kısa mesafede soğrulur.'),
  ('Okyanuslardaki büyük yüzey akıntılarını harekete geçiren başlıca etken hangisidir?', 'Sürekli esen rüzgârlar', ['Ay\'ın çekim kuvveti', 'Deniz tabanındaki volkanlar', 'Akarsuların denize dökülmesi'], 'Alizeler ve batı rüzgârları gibi kalıcı rüzgârlar yüzey suyunu sürükler; akıntıların yönünü ise Coriolis etkisi ve kıtalar biçimlendirir.'),
  ('Derindeki soğuk ve besince zengin suyun yüzeye çıkmasına ne ad verilir?', 'Yükselim (upwelling)', ['Çökelme (downwelling)', 'Gelgit kabarması', 'Termoklin oluşumu'], 'Yükselim, nitrat ve fosfat gibi besin tuzlarını ışıklı yüzey katmanına taşıyarak fitoplankton üretimini artırır.'),
  ('Bir deniz dalgasında art arda gelen iki tepe arasındaki yatay uzaklığa ne ad verilir?', 'Dalga boyu', ['Dalga yüksekliği', 'Dalga periyodu', 'Dalga genişliği ve derinliği'], 'Dalga boyu iki ardışık tepe (ya da çukur) arasındaki yatay mesafedir; yükseklik ise tepe ile çukur arasındaki dikey farktır.'),
  ('Bir iskeleden bakan gözlemci, sabit bir direğin önünden dalga tepelerinin her 6 saniyede bir geçtiğini sayıyor. Bu 6 saniye dalganın hangi özelliğidir?', 'Periyodu', ['Dalga boyu', 'Yüksekliği', 'Genliğinin iki katı olan değeri'], 'Aynı noktadan art arda iki tepenin geçmesi için geçen süre dalga periyodudur.'),
  ('Açık denizde dalgaların arasında yüzen bir şişe, dalgalar geçerken nasıl hareket eder?', 'Yerinde inip kalkarak küçük daireler çizer', ['Dalgalarla birlikte hızla kıyıya taşınır', 'Dalgaların tersine açık denize doğru gider', 'Hiç hareket etmeden yerinde sabit kalır ve sallanmaz'], 'Derin suda dalga enerjiyi taşır, suyu değil; su parçacıkları dalga geçerken yaklaşık dairesel yörüngeler çizip yerlerine döner.'),
  ('Dalga boyu 120 m, periyodu 10 s olan bir dalga dizisinin ilerleme hızı kaç m/s\'dir?', '12 m/s', ['1,2 m/s', '120 m/s', '1200 m/s'], 'Hız = dalga boyu / periyot = 120 / 10 = 12 m/s.'),
  ('Bir fırtına bölgesinden çok uzaklarda, rüzgârsız bir günde bile düzenli, uzun periyotlu ve yuvarlak tepeli dalgalar gözlenebilir. Bu dalgalara ne ad verilir?', 'Ölü dalga (soluğan)', ['Rüzgâr dalgası (çırpıntı)', 'Tsunami', 'Fırtına kabarması'], 'Fırtınanın ürettiği dalgalar oradan uzaklaştıkça düzenli ve uzun periyotlu ölü dalgalara dönüşür; binlerce kilometre yol alabilir.'),
  ('Bir kıyıda yüksek su ile alçak su arasındaki dikey yükseklik farkına ne ad verilir?', 'Gelgit aralığı', ['Dalga boyu', 'Gelgit periyodu', 'Gelgit akıntı hızı ve yönü'], 'Gelgit aralığı (genliği), kabarma ile alçalma düzeyleri arasındaki farktır; yerden yere birkaç santimetreden 15 metreyi aşan değerlere kadar değişir.'),
  ('Dünyada en büyük gelgit aralıklarının görüldüğü, kabarma ile alçalma arasındaki farkın 15 metreyi aşabildiği yer hangisidir?', 'Fundy Körfezi', ['Marmara Denizi', 'Baltık Denizi', 'Meksika Körfezi\'nin kuzey kıyıları'], 'Kanada\'daki Fundy Körfezi\'nde gelgit aralığı 16 metreye yaklaşabilir; bu, körfezin biçiminden kaynaklanan rezonansla açıklanır.'),
  ('Gelgit sırasında suyun karaya doğru, kıyıyı basacak yönde akmasına ne ad verilir?', 'Kabarma akıntısı', ['Alçalma akıntısı', 'Geri akıntı', 'Kıyı boyunca akan sürüklenme akıntısı'], 'Yükselen su haliç ve koylara doğru akarken kabarma akıntısı, çekilirken alçalma akıntısı oluşur.'),
  ('Bir koyun ağzının kum setiyle kapanması sonucunda denizden ayrılan kıyı gölüne ne ad verilir?', 'Lagün', ['Fiyort', 'Kaldera gölü', 'Haliç'], 'Kıyı kordonu koyun ağzını kapattığında arkada sığ, çoğu zaman acı sulu bir lagün kalır.'),
  ('Dalgaların kayalık kıyının tabanını oyması ve üstteki kayaların çökmesiyle oluşan dik kıyı yamacına ne ad verilir?', 'Falez (yalıyar)', ['Kıyı oku', 'Lagün', 'Kıyı kumulu (rüzgâr tepesi)'], 'Dalgalar falezin dibinde çentik açar; çentik derinleşince üstteki kaya çöker ve yalıyar geriler.'),
  ('Kıyı kumullarının üzerine yerleşen bitkilerin korunması kıyı açısından neden önemlidir?', 'Kökler kumu tutar, kumul doğal bir set olur', ['Bitkiler deniz suyunun tuzluluğunu artırır', 'Bitkiler dalgaların boyunu uzatır', 'Bitkiler kumulun hızla yürümesini ve iç bölgelere ilerlemesini sağlar'], 'Köklenen bitkiler rüzgârla taşınan kumu tutar; sağlam kumullar fırtına dalgalarının iç bölgelere ulaşmasını engeller.'),
  ('Bir akarsuyun taşıdığı alüvyonları ağzında biriktirerek denize doğru ilerleyen üçgen ya da yelpaze biçimli düzlüğe ne ad verilir?', 'Delta', ['Haliç', 'Kıyı oku', 'Abrazyon düzlüğü'], 'Adını Nil ağzının Yunan harfi Δ\'ya benzemesinden alan delta, alüvyonun kıyıda birikmesiyle oluşur.'),
  ('Haliçlerin birçok deniz balığı için \'yavru bakım alanı\' olarak önemli sayılmasının başlıca nedeni hangisidir?', 'Besin bol, su sığ ve yırtıcılardan korunaklıdır', ['Suyun tamamen tatlı ve oksijensiz olması', 'Bu alanlarda hiç akıntı ve gelgit görülmemesi', 'Haliçlerde suyun sıcaklığının hep 0 °C\'nin altında olması'], 'Akarsuların getirdiği besin maddeleri yüksek verim sağlar; sığ ve bulanık su yavruları büyük yırtıcılardan saklar.'),
  ('Kalın tortu örtüsü altında kalan engebeli tabanın düzleşmesiyle oluşan ve yeryüzündeki en düz yüzeyler arasında sayılan derin okyanus tabanlarına ne ad verilir?', 'Abisal düzlükler', ['Kıta sahanlıkları', 'Denizaltı kanyonları', 'Okyanus ortası sırtların tepe kısımları'], 'Abisal düzlükler 3000–6000 m derinliklerde, ince tortuların engebeleri doldurmasıyla oluşan çok düz alanlardır.'),
  ('Okyanus tabanından yükselen ama su yüzeyine ulaşmayan, çoğunlukla sönmüş volkanlardan oluşan tepelere ne ad verilir?', 'Deniz dağları', ['Kıta yükselimleri', 'Abisal düzlükler', 'Kıyı okları'], 'Deniz dağları tabandan en az yaklaşık 1000 m yükselen volkanik yapılardır; çevrelerindeki akıntılar zengin yaşam barındırır.'),
  ('Akıntılara karşı yüzecek güçte olmayan, suyla birlikte sürüklenerek yaşayan canlıların genel adı nedir?', 'Plankton', ['Nekton', 'Bentos', 'Perifiton'], 'Sözcük Yunanca \'sürüklenen, gezgin\' anlamına gelir; boyuttan bağımsız olarak hareketi akıntılara bağlı canlıları kapsar.'),
  ('Ton balığı, kalamar ve yunus gibi akıntılara karşı etkin biçimde yüzebilen deniz canlıları hangi grupta yer alır?', 'Nekton', ['Plankton', 'Bentos', 'Nöston'], 'Nekton, yönünü ve hızını kendisi belirleyebilen güçlü yüzücüleri kapsar.'),
  ('Deniz yıldızı, midye ve deniz kestanesi gibi deniz tabanında ya da tabanın içinde yaşayan canlılar topluca nasıl adlandırılır?', 'Bentos', ['Nekton', 'Plankton', 'Pelajik sürüler ve göçmen balıklar'], 'Bentik canlılar tabana tutunarak, tabanda sürünerek ya da tortuya gömülerek yaşar.'),
  ('Bitkisel plankton ile hayvansal plankton arasındaki temel fark hangisidir?', 'Bitkisel plankton fotosentezle kendi besinini üretir', ['Hayvansal plankton fotosentez yapar', 'Bitkisel plankton yalnızca tatlı suda bulunur', 'Hayvansal plankton yalnızca derin tabanda, ışıksız yerde yaşar'], 'Fitoplankton üreticidir; zooplankton ise fitoplanktonla ya da başka hayvanlarla beslenen tüketicidir.'),
  ('Dünya\'daki toplam fotosentezin ve atmosfere verilen oksijenin yaklaşık yarısı hangi canlılara atfedilir?', 'Okyanuslardaki fitoplanktona', ['Tropikal yağmur ormanlarına', 'Tundradaki yosun ve likenlere', 'Tarım alanlarındaki bitkilere ve çayırlara'], 'Mikroskobik fitoplankton okyanus yüzeyinin çok geniş bir alanında fotosentez yapar ve küresel birincil üretimin yaklaşık yarısını sağlar.'),
  ('Dünyanın en büyük balığı olan balina köpekbalığının beslenme biçimi için hangisi doğrudur?', 'Suyu süzerek plankton ve küçük balıklarla beslenir', ['Büyük deniz memelilerini avlar', 'Yalnızca deniz tabanındaki yosunları yer', 'Diğer köpekbalıklarını kovalayıp avlayan en hızlı yırtıcıdır'], 'Balina köpekbalığı ağzını açıp büyük miktarda suyu solungaç süzgeçlerinden geçirerek planktonu tutar.'),
  ('Resif yapan mercanlar canlılar dünyasında hangi gruba aittir?', 'Denizanası ile akraba omurgasız hayvanlar', ['Kırmızı alglere ait bitkiler', 'Kireç biriktiren bakteriler', 'Mantar ile alg ortaklığından oluşan likenler'], 'Mercanlar knidliler (sölenterler) grubundandır; her polip küçük bir hayvan olup kalsiyum karbonattan iskelet salgılar.'),
  ('Mercan resifleri okyanus tabanının çok küçük bir bölümünü kaplamasına karşın deniz türlerinin yaklaşık dörtte birine ev sahipliği yapar. Bu durum resifler için hangi yargıyı destekler?', 'Alanlarına göre olağanüstü zengin ortamlardır', ['Resiflerde tür sayısı açık okyanustan azdır', 'Resifler yalnızca mercanlardan oluşan tek türlü ortamlardır', 'Resiflerin korunması deniz yaşamını genel olarak hiç etkilemez'], 'Karmaşık üç boyutlu yapı sayısız saklanma ve beslenme yeri sunar; bu yüzden resifler \'denizlerin yağmur ormanları\' olarak anılır.'),
  ('Soğuk ve besince zengin kıyı sularında boyu onlarca metreyi bulabilen dev kahverengi alglerin oluşturduğu su altı ormanlarına ne ad verilir?', 'Kelp ormanları', ['Mangrov ormanları', 'Deniz çayırları', 'Sargassum adaları ve yüzen yosun kümeleri'], 'Kelpler tabana tutunucularıyla yapışır, gaz keseleri sayesinde ışığa doğru yükselir ve birçok canlıya barınak olur.'),
  ('Tropikal kıyılarda gelgit arası bölgede yetişen, tuzlu suya dayanıklı ağaç ve çalılardan oluşan ormanlara ne ad verilir?', 'Mangrov ormanları', ['Kelp ormanları', 'Tayga ormanları', 'Galeri ormanları'], 'Mangrovlar tropik ve subtropik kıyıların çamurlu, sakin, gelgitle su basan kesimlerinde yayılır.'),
  ('Canlıların kimyasal bir tepkimeyle kendi ışıklarını üretmesine ne ad verilir?', 'Biyolüminesans', ['Fosforesans', 'Fotosentez', 'Floresans'], 'Biyolüminesansta lusiferin adlı madde lusiferaz enziminin yardımıyla oksijenle tepkimeye girer ve ışık açığa çıkar.'),
  ('Derin deniz fener balığının başındaki ışıklı uzantının asıl işlevi nedir?', 'Avını kendine çekmek', ['Yolunu aydınlatmak için çevreyi taramak', 'Suyu ısıtmak', 'Fotosentez yapmak ve besin üretmek'], 'Uzantının ucundaki ışığı ortak yaşayan bakteriler üretir; ışığa yaklaşan küçük canlılar balığın ağzına yakalanır.'),
  ('Antarktika çevresindeki besin ağında balinalar, foklar, penguenler ve balıklar için temel besin olan küçük karidese benzer kabuklu hangisidir?', 'Antarktik kril', ['Kopepod', 'Deniz kestanesi', 'Ermiş yengeci ve istakoz'], 'Kril sürüleri fitoplanktonla beslenir ve Güney Okyanusu besin ağının merkezinde yer alır; birçok büyük hayvan doğrudan krille beslenir.'),
  ('Arktik\'te kutup ayılarının başlıca avlanma alanı ve yöntemi için hangisi doğrudur?', 'Deniz buzunda, nefes deliklerinde fok bekler', ['Açık denizde dalarak balina avlar', 'Tundra ormanlarında meyve toplar', 'Kıyı mağaralarında kış boyunca balık avlar ve depolar'], 'Kutup ayısı fokların nefes almak için buzda açtığı deliklerin başında bekler; bu nedenle deniz buzu onun için yaşamsaldır.'),
  ('Besin tuzlarının aşırı artmasıyla bir su ortamında alglerin aşırı çoğalması ve su kalitesinin bozulması sürecine ne ad verilir?', 'Ötrofikasyon', ['Tuzlanma', 'Asitlenme', 'Yükselim'], 'Ötrofikasyon \'aşırı beslenme\' anlamına gelir; göllerde ve kapalı kıyı sularında sık görülür.'),
  ('Çözünmüş oksijenin balıklar ve diğer hayvanlar için yetersiz kalacak kadar düştüğü, hayvanların kaçtığı ya da öldüğü deniz alanlarına halk arasında ne ad verilir?', 'Ölü bölge', ['Fotik bölge', 'Gelgit arası bölge', 'Yükselim bölgesi ve verimli kuşak'], 'Ölü bölgelerde oksijen çoğu hayvanın yaşamasına yetmez; yalnızca bazı bakteriler ve dayanıklı canlılar kalabilir.'),
  ('Ötrofikasyonla mücadelede kaynağa yönelik en etkili önlem hangisidir?', 'Atık suları arıtmak ve gübreyi azaltmak', ['Denize daha çok fosfor eklenmesi', 'Kıyıdaki tüm deniz çayırlarının sökülmesi', 'Denize kimyasal boya dökülerek alglerin gizlenmesi'], 'Sorunun kökü suya giren azot ve fosfordur; bu girdiyi azaltmak alg patlamalarını kalıcı olarak sınırlar.'),
  ('Deniz kaplumbağalarının yumurtladığı kumsallarda gece yapay ışıkların sınırlanmasının nedeni nedir?', 'Yumurtadan çıkan yavruların denize değil ışığa yönelerek kaybolması', ['Işığın yumurtaların kabuğunu eritmesi', 'Işığın kumun sıcaklığını donma noktasına düşürmesi', 'Işığın erkek kaplumbağaları kumsaldan uzaklaştırıp yuvaları korumasız bırakması'], 'Yavrular denize ufuktaki daha aydınlık yönü izleyerek ulaşır; yapay ışık onları karaya doğru yönlendirir.'),
  ('Türkiye kıyılarında nesli tehlike altındaki deniz memelilerinden biri olan ve kıyı mağaralarında yavrulayan tür hangisidir?', 'Akdeniz foku', ['Mors', 'Kutup ayısı', 'Leopar foku'], 'Akdeniz foku (Monachus monachus) dünyanın en nadir fok türlerinden biridir; Türkiye\'de Ege ve Akdeniz kıyılarındaki mağaraları kullanır.'),
  ('Türkiye\'nin en büyük ikinci gölü olan, çok sığ olduğu için yazın büyük bölümü kuruyup tuz tabakasıyla kaplanan ve ülkenin tuz üretiminde önemli payı olan göl hangisidir?', 'Tuz Gölü', ['Beyşehir Gölü', 'Eğirdir Gölü', 'Burdur Gölü ve Acıgöl'], 'Kapalı havzada yer alan Tuz Gölü\'nün derinliği yer yer yalnızca birkaç on santimetredir; buharlaşma yazın tuzun çökelmesini sağlar.'),
  ('Yüzölçümü bakımından dünyanın en büyük gölü olan ve suyu az tuzlu olan su kütlesi hangisidir?', 'Hazar Denizi', ['Baykal Gölü', 'Superior Gölü', 'Victoria Gölü ve Tanganika'], 'Hazar, adında \'deniz\' geçse de denizlerle bağlantısı olmayan kapalı bir göldür; tuzluluğu okyanusun yaklaşık üçte biri kadardır.'),
  ('Bir akarsuyun belirli bir kesitinden birim zamanda geçen su miktarına ne ad verilir?', 'Debi', ['Rejim', 'Eğim', 'Taban seviyesi'], 'Debi genellikle metreküp/saniye birimiyle ölçülür; akarsuyun büyüklüğünün temel göstergesidir.'),
  ('Suları denize ulaşmayan, bir göle ya da çanağa akarak buharlaşmayla kaybolan akarsu havzalarına ne ad verilir?', 'Kapalı havza', ['Açık havza', 'Delta havzası', 'Okyanus havzası ve sahanlık'], 'Konya Ovası ve Van Gölü çevresi Türkiye\'deki kapalı havza örnekleridir; buradaki sular denize akmaz.'),
  ('Bugün dünyada kıta ölçeğinde buz örtüsü (buz tabakası) bulunan iki kara kütlesi hangileridir?', 'Antarktika ve Grönland', ['Grönland ve İzlanda', 'Antarktika ve Sibirya', 'Alaska ve Kanada Arktik adaları'], 'Son buzul çağında Kuzey Amerika ve İskandinavya\'yı da örten buz tabakaları eridi; bugün yalnız Antarktika ve Grönland\'da kalmıştır.'),
  ('1872–1876 yılları arasında dünyayı dolaşarak derinlik, sıcaklık, tuzluluk ölçen ve binlerce yeni deniz türü toplayan, modern oşinografinin başlangıcı sayılan sefer hangisidir?', 'HMS Challenger seferi', ['HMS Beagle seferi', 'Kon-Tiki seferi', 'Endurance seferi ve Shackleton'], 'Challenger seferinin sonuçları 50 cildi aşan raporlarda yayımlandı ve okyanus bilimini sistemli bir bilim dalına dönüştürdü.'),
  ('Okyanus tabanının haritasının çıkarılmasında 20. yüzyılda büyük bir sıçrama yaratan gelişme hangisidir?', 'Gemilerden yankı iskandiliyle sürekli derinlik ölçümü', ['Teleskopların okyanus tabanına çevrilmesi', 'Dalgıçların tabanı elle ölçmesi', 'Gelgit ölçerlerin kıyılara yerleştirilmesi ve sayılması'], 'Yankı iskandili gemi seyir hâlindeyken bile saniyeler içinde derinlik ölçebildiği için binlerce kilometrelik kesitler elde edildi.'),
  ('Boyutu 5 milimetreden küçük plastik parçacıklarına ne ad verilir?', 'Mikroplastik', ['Nanoplankton', 'Makroplastik', 'Biyoplastik'], 'Mikroplastikler büyük plastiklerin parçalanmasıyla ya da kozmetik ve sentetik liflerden doğrudan oluşur; plankton yiyen canlılar tarafından yutulabilir.'),
  ('Denize karışan plastik bir şişenin zamanla ne olacağı için en doğru ifade hangisidir?', 'Gittikçe küçük parçalara bölünür ama kolay yok olmaz', ['Birkaç hafta içinde mikroplar tarafından tamamen ayrıştırılır', 'Deniz suyunda tuzla tepkimeye girip çözünür', 'Dibe çöküp kayaya dönüşür ve kısa sürede zararsız hâle gelir'], 'Plastikler doğada çok yavaş bozunur; ultraviyole ışık ve aşınma onları mikroplastiklere böler, toplam miktar ise uzun süre kalır.'),
  ('Denizde kaybolan ya da terk edilen ve yıllarca canlıları yakalamayı sürdüren balık ağlarına ne ad verilir?', 'Hayalet ağlar', ['Trol ağları', 'Plankton ağları', 'Sürütme ağları ve paraketeler'], 'Hayalet ağlar balıkları, kaplumbağaları ve deniz memelilerini kimse kullanmadığı hâlde yakalamaya devam eder.'),
  ('Denize dökülen ham petrolün çoğunlukla yüzeyde ince bir tabaka oluşturmasının nedeni nedir?', 'Petrolün sudan hafif olması ve suyla karışmaması', ['Petrolün suyla tepkimeye girip gaz kabarcıkları oluşturması', 'Petrolün deniz suyundan ağır olması', 'Petrolün deniz tuzunu çözerek yüzeye taşıması'], 'Petrol sudan hafiftir ve suda çözünmez; bu yüzden yüzeyde yayılarak geniş bir film oluşturur.'),
  ('Gemi gürültüsü ve sismik araştırmaların sualtında yarattığı ses kirliliği özellikle hangi canlılar için ciddi sorun oluşturur?', 'Sesle iletişim kuran balina ve yunuslar', ['Fotosentez yapan fitoplankton', 'Deniz çayırları', 'Kıyı kumullarındaki bitkiler ve otsu türler'], 'Ses suda çok uzağa gider; yüksek gürültü balinaların seslerini maskeler, davranışlarını bozar ve işitme hasarına yol açabilir.'),
  ('Aynı göl suyu 5 °C\'de ve 25 °C\'de oksijenle doyuruluyor. Hangi durumda suda daha fazla oksijen çözünmüş olur?', '5 °C\'deki suda', ['25 °C\'deki suda', 'İkisinde de tam olarak aynı', 'Sıcaklıktan bağımsız olarak hangisi daha uzun beklerse'], 'Gazların sudaki çözünürlüğü sıcaklık düştükçe artar; soğuk su doygunlukta ılık sudan belirgin biçimde fazla oksijen tutar.'),
  ('Bir güneş damıtıcısında tuzlu su siyah bir kapta ısınır, buhar eğik cam kapağın altında yoğunlaşıp bir oluğa akar. Oluktaki suyun tatlı olmasının nedeni nedir?', 'Buharlaşmada yalnızca suyun buhara geçmesi', ['Camın tuzu süzmesi', 'Siyah kabın tuzu soğurması', 'Güneş ışığının tuzu parçalaması ve yok etmesi'], 'Tuz uçucu değildir; buharlaşan yalnızca sudur. Yoğuşan su bu yüzden tuzsuzdur, tuz kapta kalır.'),
  ('Tuzluluğu binde 35 olan deniz suyunun 200 kilogramı bir tuzlada tamamen buharlaştırılırsa geriye yaklaşık kaç kilogram tuz kalır?', '7 kg', ['35 kg', '3,5 kg', '70 kg'], 'Binde 35, her 1000 g deniz suyunda 35 g tuz demektir: 200 kg × 0,035 = 7 kg.'),
  ('Sesin deniz suyundaki hızı 1500 m/s alınırsa 4500 m derinlikteki bir tabandan yansıyan iskandil sinyali gönderildikten kaç saniye sonra gemiye döner?', '6 saniye', ['3 saniye', '1,5 saniye', '4,5 saniye'], 'Ses 4500 m gidip 4500 m döner: 9000 / 1500 = 6 s.'),
  ('Bir dalgıç 25 m derinliğe iniyor. Yüzeydeki hava basıncı 1 atm ve her 10 m deniz suyu 1 atm eklediğine göre dalgıcın üzerindeki mutlak basınç kaç atm\'dir?', '3,5 atm', ['2,5 atm', '25 atm', '26 atm'], 'Su sütunu 25 / 10 = 2,5 atm ekler; buna 1 atm hava basıncı eklenince toplam 3,5 atm olur.'),
  ('Yüzen bir buzdağının su üstünde kalan kısmının hacmi 150 m³ olarak ölçülüyor. Buzdağının yaklaşık onda biri su üstünde kaldığına göre toplam hacmi yaklaşık kaç m³\'tür?', '1500 m³', ['165 m³', '1350 m³', '15 000 m³'], 'Görünen kısım toplamın onda biri olduğundan toplam hacim 150 / 0,1 = 1500 m³\'tür.'),
  ('Bir kıyıda deniz seviyesi yılda ortalama 3,3 mm yükselmektedir. Bu hız değişmezse 30 yılda deniz seviyesi yaklaşık kaç santimetre yükselir?', 'Yaklaşık 10 cm', ['Yaklaşık 1 cm', 'Yaklaşık 33 cm', 'Yaklaşık 100 cm'], '3,3 × 30 = 99 mm, yani yaklaşık 10 cm\'dir.'),
  ('Resiflerde bazı küçük balıkların büyük balıkların derisindeki parazitleri ve ölü dokuyu temizlemesi, büyük balığın da onları yememesi hangi ilişki türüne örnektir?', 'Karşılıklı yarar (mutualizm)', ['Asalaklık', 'Avcılık', 'Rekabet ve bölge savunması (karşı karşıya gelme)'], 'Temizlikçi balık besin elde eder, büyük balık ise parazitlerinden kurtulur; iki taraf da yarar sağlar.'),
  ('Balinaların, okyanusta yaşamalarına karşın düzenli olarak yüzeye çıkmak zorunda olmalarının nedeni nedir?', 'Akciğerle soluk alan memeliler olmaları', ['Gözlerinin yalnız havada görebilmesi', 'Yüzeyde tuzsuz su içmeleri', 'Derinde suyun onları sürekli yukarı itmesi'], 'Balinaların solungacı yoktur; havayı başlarının üstündeki soluk deliklerinden alırlar.'),
  ('Mavi balina gibi dünyanın en büyük hayvanlarının ağızlarındaki balen plakaları hangi beslenme biçimine uyumdur?', 'Suyu süzüp küçük canlıları yakalamaya', ['Büyük balıkları dişleriyle parçalamaya', 'Deniz tabanındaki kayaları kemirmeye', 'Diğer balinaları avlayıp onlarla beslenmeye'], 'Balen, keratinden oluşan elek benzeri plakalardır; balina ağız dolusu suyu dışarı iterken küçük avları içeride tutar.'),
  ('Yunus ve kaşalot gibi dişli balinaların karanlık ya da bulanık suda avlarını bulmak için çıkardıkları seslerin yankısından yararlanmasına ne ad verilir?', 'Ekolokasyon', ['Biyolüminesans', 'Fotosentez', 'Elektroresepsiyon'], 'Hayvan kısa ses darbeleri gönderir ve dönen yankıdan avın yerini, büyüklüğünü ve hareketini çıkarır.'),
  ('Balina ve fok gibi soğuk sularda yaşayan deniz memelileri vücut ısısını korumak için en çok neye güvenir?', 'Derinin altındaki kalın yağ tabakasına', ['Pullarına', 'Sürekli yüzeyde güneşlenmeye', 'Kanlarındaki antifriz proteinlerine ve soğuk kana'], 'Kalın yağ katmanı yalıtım sağlar; ayrıca enerji deposu ve yüzerlik kaynağı olarak da işe yarar.'),
  ('Balık avında hedeflenmeyen türlerin (yunus, kaplumbağa, yavru balık gibi) ağlara takılarak yakalanmasına ne ad verilir?', 'Hedef dışı av', ['Sürdürülebilir av', 'Kültür balıkçılığı', 'Yükselim avı'], 'Hedef dışı av birçok türü tehdit eder; ağ biçimi ve av yöntemi değiştirilerek azaltılabilir.'),
  ('Birçok ülkede her balık türü için en küçük av boyu belirlenir. Bu kuralın temel amacı nedir?', 'Balıkların yakalanmadan önce üreyebilmesi', ['Balıkların daha lezzetli olmasını sağlamak', 'Ağların daha hafif olmasını sağlamak', 'Balıkların daha hızlı yüzmesini sağlamak'], 'Üreme yaşına gelmemiş bireylerin korunması, stoğun kendini yenileyebilmesi için gereklidir.'),
  ('Küresel ölçekte insanların çektiği tatlı suyun en büyük bölümü hangi amaçla kullanılır?', 'Tarımsal sulama', ['Evlerde içme ve temizlik', 'Sanayi üretimi', 'Yüzme havuzları ve parklar'], 'Dünya genelinde tatlı su çekiminin yaklaşık %70\'i tarımda kullanılır; bu yüzden sulama verimliliği su yönetiminin kilit konusudur.'),
  ('Salma sulama yerine damla sulamaya geçilmesi su tasarrufunu en çok hangi yoldan sağlar?', 'Suyun kök bölgesine verilip kayıpların azalması', ['Bitkinin daha az fotosentez yapması', 'Toprağın tuzluluğunun artırılması', 'Yağmurun bitkiye ulaşmasının engellenmesi ve suyun depolanması'], 'Damla sulamada su az ve sık verilir; geniş yüzeyden buharlaşma ve tarla dışına akış çok azalır.'),
  ('Yağmur suyunun çatılardan toplanıp depolanarak bahçe sulaması ya da tuvalet gibi işlerde kullanılmasına ne ad verilir?', 'Yağmur suyu hasadı', ['Tuzdan arındırma', 'Ters ozmoz', 'Akifer tuzlanması ve sızması'], 'Yağmur suyu hasadı şebeke suyuna olan talebi azaltır ve kentlerde ani yüzey akışını da bir ölçüde sınırlar.'),
  ('Hawaii ve İzlanda gibi volkanik adalarda bazı kumsalların kum rengi neden siyahtır?', 'Kum, parçalanmış koyu bazalt ve volkanik camdır', ['Kum petrolle kirlenmiştir', 'Kum kömür tozundan oluşur', 'Kum gece sürekli gölgede kalır'], 'Sıcak lav denize ulaşınca hızla soğuyup parçalanır; koyu renkli bazalt ve volkanik cam taneleri siyah kumu oluşturur.'),
  ('Tropik mercan adalarındaki bembeyaz kumsalların kumu büyük ölçüde nereden gelir?', 'Mercan, kabuk ve kalkerli alg parçalarından', ['Kıtalardan taşınan kuvarstan', 'Volkanik bazalttan', 'Deniz suyundan doğrudan çöken sofra tuzu kristallerinden'], 'Bu kumsallar biyojen karbonat kumundan oluşur; papağan balıkları gibi canlılar ve dalgalar kireç iskeletlerini öğüterek kuma dönüştürür.'),
  ('Gözenekliliği %30 olan, tamamen suya doymuş 2 m³ kum katmanının gözeneklerinde yaklaşık kaç litre su bulunur?', '600 L', ['60 L', '300 L', '1500 L'], 'Gözeneklilik boşluk hacminin toplam hacme oranıdır: 2 m³ × 0,30 = 0,6 m³ = 600 litre.'),
  ('Bir kentin hızla büyüyüp toprak yüzeylerin asfalt ve betonla kaplanması yağış suyunun dağılımını nasıl etkiler?', 'Yüzey akışı artar, toprağa süzülme azalır', ['Süzülme artar, yüzey akışı azalır', 'Buharlaşma tamamen durur', 'Yağış miktarı kendiliğinden azalır'], 'Geçirimsiz yüzeyler suyun toprağa girmesini engeller; su hızla kanalizasyona ve derelere akar, ani taşkın riski artar, akifer beslenmesi azalır.'),
  ('Su döngüsünde yağmur suyunun toprak yüzeyinden içeri girmesine ne ad verilir?', 'Süzülme', ['Terleme', 'Yoğuşma', 'Süblimleşme'], 'Toprağa giren suyun bir kısmı bitkilerce alınır, bir kısmı daha derine sızarak yeraltı suyunu besler.'),
  ('Açık bir yaz gecesinin sabahında çimenlerin üzerinde su damlacıkları görülür. Bu damlacıkların kaynağı nedir?', 'Havadaki su buharının soğuyan yüzeylerde yoğuşması', ['Yağmurun gece boyunca yağması', 'Toprağın altından suyun kılcallıkla çıkması', 'Çimenlerin içindeki suyun dışarı sızması'], 'Açık gecelerde yüzeyler ışımayla soğur; hava çiy noktasının altına inince buhar yüzeylerde sıvı damlacık olarak yoğuşur ve çiy oluşur.'),
  ('Bir bölgede yıllık yağış 600 mm, buharlaşma ve terleme ile kaybolan su 450 mm\'dir. Yeraltına süzülme ve akarsu akışı için kalan su yaklaşık kaç mm\'dir?', '150 mm', ['1050 mm', '450 mm', '75 mm'], 'Su bütçesinde yağış, buharlaşma-terleme ile akış ve süzülmenin toplamına eşittir: 600 − 450 = 150 mm.'),
  ('Dünyadaki tatlı suyun büyük bölümünü tek başına depolayan buz kütlesi hangisidir?', 'Antarktika buz tabakası', ['Grönland buz tabakası', 'Alp buzulları', 'Himalaya buzulları'], 'Antarktika buz tabakası Dünya\'daki tatlı suyun yarıdan fazlasını, buzul buzunun ise yaklaşık %90\'ını barındırır.'),
  ('Bir şehir yeraltı suyunu yılda 50 milyon m³ çekerken akifer yağışla yalnızca yılda 30 milyon m³ beslenmektedir. Bu durum sürerse ne beklenir?', 'Su tablası her yıl düşer, kuyular derinleştirilmek zorunda kalır', ['Akifer kendiliğinden daha hızlı beslenmeye başlar', 'Su tablası sabit kalır', 'Akiferdeki su tuzdan arınır'], 'Çekim beslenmeyi yılda 20 milyon m³ aşıyor; bu açık depolanmış sudan karşılanacağı için su düzeyi sürekli alçalır.'),
  ('Deniz suyunda kütlece klorürden sonra en bol bulunan ikinci iyon hangisidir?', 'Sodyum', ['Magnezyum', 'Kalsiyum', 'Potasyum'], 'Bir kilogram deniz suyunda yaklaşık 19 g klorür ve 11 g sodyum bulunur; sülfat ve magnezyum bunları izler.'),
  ('Tuzluluğu binde 35 olan bir deniz suyundan 10 kg örnek alınıyor. Bu örnekte yaklaşık kaç gram çözünmüş tuz bulunur?', '350 g', ['35 g', '3,5 g', '3500 g'], 'Binde 35 tuzluluk, her 1000 g suda 35 g tuz demektir: 10 000 g × 0,035 = 350 g.'),
  ('Okyanusun en üstünde rüzgâr ve dalgaların karıştırdığı, sıcaklığın derinlikle neredeyse değişmediği katmana ne ad verilir?', 'Karışım katmanı', ['Termoklin', 'Abisal katman', 'Haloklin'], 'Rüzgâr ve dalgalar yüzeydeki birkaç on metrelik suyu karıştırır; bu karışım katmanının altında sıcaklığın hızla düştüğü termoklin başlar.'),
  ('Açık okyanusta derinliği 3000 metreyi aşan sulardaki tipik sıcaklık hangi aralıktadır?', 'Yaklaşık 0–4 °C', ['Yaklaşık 10–15 °C', 'Yaklaşık 20–25 °C', 'Yaklaşık −10 ile −20 °C'], 'Derin okyanus, kutup denizlerinde batan soğuk sularla dolduğundan tropiklerde bile birkaç dereceden ılık değildir.'),
  ('Güneşli bir yaz öğleden sonra kum sıcacıkken deniz suyu serindir. Bu fark en çok hangi özelliğe dayanır?', 'Suyun özgül ısısının kumdan çok daha yüksek olması', ['Suyun kumdan daha fazla ışık yansıtması', 'Kumun suya göre daha az ışık soğurması', 'Denizin sürekli buharlaşarak tamamen soğuması'], 'Aynı ısıyı alan 1 kg su, 1 kg kuma göre çok daha az ısınır; suyun özgül ısısı yaklaşık 4,18 J/g°C iken kumunki 1 J/g°C dolayındadır.'),
  ('Yağmur suyu bir yaprağın üzerinde küçük yuvarlak damlalar halinde durur. Bu görünüşün temel nedeni hangisidir?', 'Yüzey geriliminin damlayı en küçük yüzeyli biçime çekmesi', ['Su moleküllerinin birbirini itmesi', 'Yaprağın suyu emerek şişmesi', 'Havanın damlayı aşağıdan yukarı doğru itmesi'], 'Yüzeydeki moleküller içeriye doğru çekilir; bu çekim damlanın yüzey alanını en aza indirerek küresel biçime yaklaştırır.'),
  ('Denizcilikte yatay uzaklığı ölçmek için kullanılan 1 deniz mili kaç metreye eşittir?', '1852 metre', ['1609 metre', '1000 metre', '2000 metre'], 'Deniz mili, enlem derecesinin bir dakikalık yayına dayanır ve uluslararası olarak 1852 m kabul edilmiştir; bir knot saatte bir deniz milidir.'),
  ('Eski denizcilerin su derinliğini ölçmede kullandığı bir kulaç yaklaşık 1,8 metredir. Çıkrığına sarılı kurşunlu ip 25 kulaç suya indiğinde kabaca kaç metre derinlik bulunur?', 'Yaklaşık 45 metre', ['Yaklaşık 14 metre', 'Yaklaşık 4,5 metre', 'Yaklaşık 450 metre'], '25 × 1,8 m = 45 m. Bu yöntem kıyıya yakın seyirlerde derinlik tayininde kullanılmıştır.'),
  ('Dalga boyu 60 m olan ve dalga tepeleri bir noktadan 8 saniyede bir geçen deniz dalgasının ilerleme hızı kaç m/s\'dir?', '7,5 m/s', ['480 m/s', '0,13 m/s', '68 m/s'], 'Hız = dalga boyu / periyot = 60 / 8 = 7,5 m/s.'),
  ('Bir yüzme havuzunda su yüzeyinde dalga oluşturan öğrenci, aynı dalganın periyodunu 2 saniye, hızını 1,5 m/s ölçüyor. Dalga boyu kaç metredir?', '3 m', ['0,75 m', '1,33 m', '3,5 m'], 'λ = v · T = 1,5 × 2 = 3 m.'),
  ('Dünya\'daki en büyük mercan resifi sistemi olan ve kuzeydoğu Avustralya açıklarında uzanan yapıya ne ad verilir?', 'Büyük Set Resifi', ['Maldiv Atolü', 'Kızıldeniz Setleri', 'Ningaloo Kıyısı'], 'Büyük Set Resifi yaklaşık 2300 km uzunluğunda binlerce ayrı resiften oluşur ve uzaydan seçilebilecek büyüklükte canlı kökenli bir yapıdır.'),
  ('Denizanası aslında bir balık değildir. Hangi hayvan grubuna girer?', 'Knidarlar', ['Omurgalılar', 'Eklembacaklılar', 'Süngerler'], 'Denizanaları, mercanlar ve deniz gelinciği knidarlardır; hayvanın dokusu iki hücre katmanından yapılır ve yakıcı hücreler taşır.'),
  ('Meriç Nehri Türkiye\'den hangi denize dökülür?', 'Ege Denizi', ['Karadeniz', 'Marmara Denizi', 'Akdeniz'], 'Meriç Nehri Bulgaristan\'da doğup Türkiye-Yunanistan sınırı boyunca akar ve Enez yakınlarında Ege Denizi\'ne ulaşır.'),
  ('Yeryüzünde debisi en yüksek olan akarsu hangisidir?', 'Amazon', ['Nil', 'Mississippi', 'Yangtze'], 'Amazon\'un ortalama debisi saniyede yaklaşık 200 000 metreküptür; sonraki akarsulardan kat kat fazladır. En uzun nehir ise Nil ya da Amazon olarak tartışılır, debi bakımından ise bir şüphe yoktur.'),
  ('Bir yelkenli teknenin direğinden denize bırakılan bir şamandıra, bir gün içinde iki kez yükselip iki kez alçalıyor. Şamandırayı hareket ettiren olay hangisidir?', 'Gelgit', ['Dalgaların kırılması', 'İç dalgaların oluşması', 'Yüzey gerilimi'], 'Yarı günlük gelgitte günde iki yüksek ve iki alçak su görülür; gelgit dalgası uzun dalga boyuyla suyu yükseltip alçaltır.'),
  ('Bir denizaltının 300 m derinlikte dış yüzeye uygulanan hidrostatik basıncı atmosfer basıncı dışında yaklaşık kaç atmosferdir? (Her 10 m için yaklaşık 1 atm)', 'Yaklaşık 30 atm', ['Yaklaşık 3 atm', 'Yaklaşık 300 atm', 'Yaklaşık 0,3 atm'], 'Her 10 m suda 1 atm eklenir: 300 / 10 = 30 atm. Toplam basınç yüzey basıncıyla birlikte yaklaşık 31 atm olur.'),
  ('Bir plajda dalgaların kıyıdan geri çekilirken oluşturduğu, yüzeyden kıyıdan açığa doğru hızlı akan dar şeride ne ad verilir?', 'Yırtıcı akıntı', ['Gelgit akıntısı', 'Yükselim', 'Haloklin'], 'Kıyıya itilen suyun açığa dönüş yoludur; yüzücüleri sürükleyebildiğinden kıyıya paralel yüzerek çıkılması önerilir.'),
];
